mapper.insert:
INSERT INTO appointment (
    appointment_no, request_id, patient_id, doctor_id, schedule_slot_id,
    schedule_date, start_time, end_time, status
) VALUES (
    #{appointment.appointmentNo}, #{appointment.requestId}, #{appointment.patientId}, #{appointment.doctorId}, #{appointment.scheduleSlotId},
    #{appointment.scheduleDate}, #{appointment.startTime}, #{appointment.endTime}, #{appointment.status}
)

mapper.select:
SELECT id, appointment_no, request_id, patient_id, doctor_id, schedule_slot_id,
       schedule_date, start_time, end_time, status, created_at
FROM appointment WHERE id = #{id}

SELECT appointment.id, appointment.appointment_no, patient.real_name AS patient_name, department.name AS department_name, appointment.schedule_slot_id, appointment.schedule_date, slot.session_name, appointment.start_time, appointment.end_time, appointment.status FROM appointment INNER JOIN patient ON patient.id = appointment.patient_id INNER JOIN doctor ON doctor.id = appointment.doctor_id INNER JOIN department ON department.id = doctor.department_id LEFT JOIN doctor_schedule_slot slot ON slot.id = appointment.schedule_slot_id WHERE appointment.doctor_id = #{doctorId} AND appointment.schedule_date = #{scheduleDate}
AND appointment.status = #{status}
ORDER BY appointment.start_time ASC, appointment.id ASC

mapper.update:
UPDATE appointment SET status = 'COMPLETED'
WHERE id = #{id}
  AND doctor_id = #{doctorId}
  AND status = 'BOOKED'
